import {DRAFT_KEY,EMPTY_CONFIGURATION,validateConfiguration,assessCompatibility} from './custom-virus.mjs';
import {parseConfigurationCsv,CSV_LIMIT,CSV_TEMPLATE} from './custom-data.mjs';
const panel=document.createElement('section');panel.id='targetDemo';panel.className='custom-virus-setup';
panel.innerHTML=`<fieldset class="custom-virus-info"><legend><span class="step-number">01</span> Virus details</legend><p class="field-help">Enter a name and two simple properties. We handle the available reference targets automatically.</p><div class="custom-virus-fields"><label>Virus Name<input id="targetDemoName" name="virusName" maxlength="100" required placeholder="Enter a virus name" autocomplete="off"><small>The name shown with your saved configuration.</small></label><label>Virus Type<select id="customGenome" name="genomeType" required><option value="">Choose a type</option><option value="RNA">RNA</option><option value="DNA">DNA</option><option value="unknown">Not known</option></select><small>The kind of genetic material; descriptive only.</small></label><label>Virus Structure<select id="customEnvelope" name="envelope" required><option value="">Choose a structure</option><option value="enveloped">Enveloped</option><option value="non-enveloped">Non-enveloped</option><option value="unknown">Not known</option></select><small>Whether the virus has an outer lipid envelope; descriptive only.</small></label><label class="custom-wide"><span>Notes <span class="muted">(optional)</span></span><textarea id="targetDemoDescription" name="description" maxlength="1000" rows="3" placeholder="Briefly describe your research question"></textarea></label></div></fieldset>
<details class="custom-virus-properties"><summary>Advanced Settings <span class="tag">OPTIONAL</span></summary><p class="field-help">Optional notes and data. These details label your demo; they do not change the reference-model predictions.</p><div class="custom-virus-fields"><label><span>Virus family <span class="muted">(optional)</span></span><input id="customFamily" name="family" maxlength="100" placeholder="Enter the family, if known"><small>Descriptive taxonomy; unknown families can still be saved.</small></label></div><div class="custom-model-inputs"><strong>What can the existing models actually read?</strong><p>The reference models read compound descriptors and molecular fingerprint bits. They were trained on artificial activity labels. They do not accept a custom viral genome, envelope, protein description or biochemical property as a validated predictor.</p><p>No viral-property sliders are shown because no such numeric inputs are supported. Additional molecular or protein details can be recorded in Description, but are not used to invent predictions.</p></div></details>
<div class="custom-compatibility" id="customCompatibility" role="status" aria-live="polite"><span class="tag">MODEL COMPATIBILITY</span><h3>Synthetic reference demo</h3><p>Your virus details label this session. Screening uses the existing synthetic reference targets, not a model trained against your custom virus.</p></div><p class="field-help" id="customDraftStatus" role="status">Your draft is saved on this device as you type.</p><button type="button" class="button light" id="targetDemoExport" disabled>Export configuration</button>`;
const setup=document.querySelector('#screenForm .setup-fields'),typeStep=setup.querySelector('.setup-step');typeStep.classList.add('custom-context-step');typeStep.hidden=true;setup.before(typeStep,panel);const libraryOptions=setup.querySelector('.setup-step');libraryOptions.classList.add('custom-library-options');libraryOptions.querySelector('legend').textContent='Available compound library';panel.querySelector('.custom-virus-properties').append(libraryOptions);setup.remove();

const ownData=document.createElement('details');ownData.className='custom-own-data';ownData.id='customOwnData';
ownData.innerHTML=`<summary>Add Your Own Data <span class="tag">OPTIONAL</span></summary><p class="field-help">Enter descriptive values or import a configuration CSV. These values are metadata only: uploads do not train a model or make a custom virus compatible.</p><div id="customDataRows"></div><button class="button light" id="addCustomData" type="button">Add a value</button><div class="custom-csv-input"><label for="customCsvFile">Import CSV <span class="muted">(processed on this device, up to 64 KB)</span></label><input id="customCsvFile" type="file" accept=".csv,text/csv" aria-describedby="customCsvHelp"><p class="field-help" id="customCsvHelp">Import one configuration row using the template, or descriptive rows with headers <code>property,value,unit</code>. Compound-feature files, prediction files and model training are not supported by this importer.</p><button type="button" class="button light" id="customCsvTemplate">Download configuration template</button><p id="customCsvStatus" role="status" class="field-help"></p><div id="customCsvPreview" hidden><h3>Preview uploaded data</h3><div class="custom-data-table"><table><thead><tr><th>Field</th><th>Imported value</th></tr></thead><tbody></tbody></table></div><button type="button" class="button light" id="applyCustomCsv" disabled>Apply previewed data</button></div></div>`;
panel.querySelector('.custom-virus-properties').after(ownData);
const review=document.createElement('section');review.className='custom-review';review.id='customReview';
review.innerHTML=`<h3>Configuration preview</h3><p id="customReviewStatus" role="status">Your details are saved as you type.</p><dl id="customReviewValues"></dl><button class="button light" type="button" id="resetCustomConfiguration">Clear configuration</button><p id="customInputFeedback" role="alert" hidden></p>`;

const advanced=panel.querySelector('.custom-virus-properties');advanced.querySelector('.custom-virus-fields').prepend(panel.querySelector('#targetDemoDescription').closest('label'));advanced.append(ownData,review);const autoSummary=document.querySelector('.checkbox-label');advanced.append(autoSummary);document.querySelector('#autoSummary').checked=false;
const form=document.querySelector('#screenForm'),controls=[...panel.querySelectorAll('[name]')],byId=id=>document.getElementById(id);
let callbacks={},study,configuration={...EMPTY_CONFIGURATION,additionalData:[]},compatibility=null,busy=false,storageAvailable=true,reviewed=false,lastReferenceSession=null,pendingCsv=null,importSequence=0;
const labels={virusName:'Virus Name',genomeType:'Virus Type',envelope:'Virus Structure',description:'Notes',family:'Virus family',library:'Compound library'};
function dataRows(){return [...byId('customDataRows').children].map(row=>Object.fromEntries([...row.querySelectorAll('input')].map(input=>[input.dataset.field,input.value])));}
function read(){return {...EMPTY_CONFIGURATION,...Object.fromEntries(controls.map(input=>[input.name,input.value])),targetProtein:'All supported reference targets (automatic)',library:byId('library').value,additionalData:dataRows()};}
function addDataRow(item={name:'',value:'',unit:''}){
 if(byId('customDataRows').children.length>=20){byId('customCsvStatus').textContent='Add at most 20 descriptive data rows.';return;}
 const row=document.createElement('div');row.className='custom-data-row';
 for(const [key,title,limit] of [['name','Property name',80],['value','Value',200],['unit','Units (optional)',30]]){const label=document.createElement('label');label.textContent=title;const input=document.createElement('input');input.dataset.field=key;input.maxLength=limit;input.value=typeof item[key]==='string'?item[key]:'';input.setAttribute('aria-label',`${title} for descriptive data row ${byId('customDataRows').children.length+1}`);label.append(input);row.append(label);}
 const remove=document.createElement('button');remove.type='button';remove.className='button light';remove.textContent='Remove';remove.setAttribute('aria-label','Remove this descriptive data row');remove.onclick=()=>{row.remove();save();};row.append(remove);byId('customDataRows').append(row);
}
function write(c){controls.forEach(input=>{input.value=typeof c[input.name]==='string'?c[input.name]:EMPTY_CONFIGURATION[input.name];});byId('library').value=c.library==='focused'?'focused':'all';byId('customDataRows').replaceChildren();if(Array.isArray(c.additionalData))c.additionalData.slice(0,20).forEach(addDataRow);}
function renderReview(){
 const list=byId('customReviewValues');list.replaceChildren();for(const [key,label] of Object.entries(labels)){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=configuration[key]||'Not entered';list.append(dt,dd);}
 for(const item of configuration.additionalData||[]){if(!item.name&&!item.value&&!item.unit)continue;const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=item.name||'Unnamed property';dd.textContent=(item.value||'Missing value')+(item.unit?' '+item.unit:'')+' (descriptive only)';list.append(dt,dd);}
 byId('customReviewStatus').textContent='Session details only. All available reference targets are screened separately; scores are not combined.';
}
function notify(){renderReview();callbacks.onConfiguration?.({...configuration,additionalData:configuration.additionalData.map(r=>({...r}))},compatibility);byId('selectedVirusName').textContent=configuration.virusName.trim()||'Your custom virus';byId('targetName').textContent=configuration.targetProtein.trim()||'Choose a target protein';}
function persist(){try{localStorage.setItem(DRAFT_KEY,JSON.stringify(configuration));byId('customDraftStatus').textContent='Draft saved on this device.';}catch{storageAvailable=false;byId('customDraftStatus').textContent='Browser storage is unavailable. Keep this page open and export the configuration.';}}
function save(){configuration=read();compatibility=null;reviewed=false;lastReferenceSession=null;byId('targetDemoExport').disabled=false;byId('customInputFeedback').hidden=true;persist();const box=byId('customCompatibility');box.classList.remove('checked');box.querySelector('h3').textContent='Synthetic reference demo';box.querySelector('p').textContent='Your virus details label this session. Predictions come from the existing reference targets, not from a model trained against your custom virus.';notify();}
export function configureTargetDemo(options){callbacks=options;study=options.study;try{const saved=JSON.parse(localStorage.getItem(DRAFT_KEY)||'null');if(saved&&typeof saved==='object'&&!Array.isArray(saved))write({...EMPTY_CONFIGURATION,...saved});}catch{storageAvailable=false;}configuration=read();reviewed=false;notify();byId('customDraftStatus').textContent=storageAvailable?'Draft saved locally; edit any field to update it.':'Local draft storage is unavailable; export your configuration after review.';}
export function setTargetDemoVisible(){panel.hidden=false;}
function onEdit(event){if(event.target.type==='file')return;if(panel.contains(event.target)||event.target.id==='library')save();}
form.addEventListener('input',onEdit);form.addEventListener('change',onEdit);
function showError(error){byId('customInputFeedback').textContent=error.message;byId('customInputFeedback').hidden=false;byId('customCompatibility').querySelector('h3').textContent='Screening could not start';byId('customCompatibility').querySelector('p').textContent=error.message;}
byId('addCustomData').onclick=()=>{if(busy)return;addDataRow();save();byId('customDataRows').lastElementChild?.querySelector('input').focus();};
byId('resetCustomConfiguration').onclick=()=>{
 if(busy)return;importSequence++;pendingCsv=null;write({...EMPTY_CONFIGURATION,additionalData:[]});byId('customCsvFile').value='';byId('customCsvPreview').hidden=true;byId('applyCustomCsv').disabled=true;byId('customCsvStatus').textContent='';byId('customInputFeedback').hidden=true;save();try{localStorage.removeItem(DRAFT_KEY);}catch{}byId('customDraftStatus').textContent='Configuration cleared. Saved compounds and screening history were kept.';byId('targetDemoName').focus();
};
byId('customCsvFile').onchange=async()=>{
 const sequence=++importSequence,file=byId('customCsvFile').files[0];pendingCsv=null;byId('customCsvPreview').hidden=true;byId('applyCustomCsv').disabled=true;
 if(!file){byId('customCsvStatus').textContent='No CSV selected.';return;}
 try{if(!/\.csv$/i.test(file.name))throw new Error('Choose a .csv file.');if(file.size>CSV_LIMIT)throw new Error('CSV files must be no larger than 64 KB.');byId('customCsvStatus').textContent='Reading local CSV...';const result=parseConfigurationCsv(await file.text());if(sequence!==importSequence)return;pendingCsv=result;const tbody=byId('customCsvPreview').querySelector('tbody');tbody.replaceChildren();result.preview.forEach(item=>{const row=document.createElement('tr');for(const value of [item.field,item.value]){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}tbody.append(row);});byId('customCsvPreview').hidden=false;byId('applyCustomCsv').disabled=false;byId('customCsvStatus').textContent=`${result.preview.length} values validated. Preview before applying; your current configuration has not changed.`;}catch(error){if(sequence!==importSequence)return;byId('customCsvStatus').textContent=error.message;}
};
byId('applyCustomCsv').onclick=()=>{
 if(!pendingCsv||busy)return;
 try{const current=read(),next={...current,...pendingCsv.patch};if(pendingCsv.kind==='descriptive'){next.additionalData=[...current.additionalData.filter(r=>r.name||r.value||r.unit),...pendingCsv.patch.additionalData];if(next.additionalData.length>20)throw new Error('The combined configuration may contain at most 20 descriptive rows.');const seen=new Set();for(const row of next.additionalData){const key=row.name.trim().toLowerCase();if(seen.has(key))throw new Error(`Duplicate property name: ${row.name}.`);seen.add(key);}}
 write(next);pendingCsv=null;save();byId('applyCustomCsv').disabled=true;byId('customCsvStatus').textContent='Previewed data applied. Edit any value, then start screening.';}catch(error){byId('customCsvStatus').textContent=error.message;}
};
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type})),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
byId('customCsvTemplate').onclick=()=>download('fairuz-configuration-template.csv',CSV_TEMPLATE,'text/csv');
export async function runTargetDemo(){
 if(busy||!form.reportValidity())return;
 try{
  configuration=validateConfiguration(read());write(configuration);reviewed=true;busy=true;callbacks.onBusy?.(true);panel.querySelectorAll('input,select,textarea,button').forEach(c=>c.disabled=true);byId('library').disabled=true;form.setAttribute('aria-busy','true');byId('progress').hidden=false;byId('progress').textContent='Checking target and model compatibility...';
  await new Promise(resolve=>setTimeout(resolve,20));compatibility=assessCompatibility(configuration,study);persist();
  const result=await callbacks.onScreen?.(JSON.parse(JSON.stringify(configuration)),{withSummary:byId('autoSummary').checked});
  if(!result)throw new Error('No reference screening was completed.');lastReferenceSession=result;
  const box=byId('customCompatibility');box.classList.add('checked');box.querySelector('h3').textContent=`${result.completed} reference targets screened`;
  box.querySelector('p').textContent='Results are grouped by the original reference target. Your virus details are a demo label; these are not activity predictions against your custom virus.';notify();

 }catch(error){showError(error);}
 finally{busy=false;panel.querySelectorAll('input,select,textarea,button').forEach(c=>c.disabled=false);byId('applyCustomCsv').disabled=!pendingCsv;byId('targetDemoExport').disabled=!reviewed;form.removeAttribute('aria-busy');byId('progress').hidden=true;callbacks.onBusy?.(false);}
}
byId('targetDemoExport').onclick=()=>{try{configuration=validateConfiguration(read());reviewed=true;}catch(error){showError(error);return;}download('fairuz-custom-virus-configuration.json',JSON.stringify({schemaVersion:2,type:'custom-virus-configuration',createdAt:new Date().toISOString(),configuration,validated:true,referenceSession:lastReferenceSession,customVirusInference:false,compatibility:compatibility||{supported:null,code:'NOT_CHECKED'},screeningPerformed:Boolean(lastReferenceSession),screeningScope:'synthetic-reference-only',predictions:[],biologicalEvidence:false},null,2),'application/json');};
